package com.lims.dao;

import com.lims.model.*;
import com.lims.util.DBContext;
import java.sql.*;import java.util.*;import java.util.logging.Level;import java.util.logging.Logger;

public class ExportDAO {
 private static final Logger LOG=Logger.getLogger(ExportDAO.class.getName());
 public boolean hasRole(int id,String role){String q="SELECT COUNT(*) FROM USERS u JOIN USER_ROLES ur ON ur.UserID=u.UserID JOIN ROLES r ON r.RoleID=ur.RoleID WHERE u.UserID=? AND u.Status='ACTIVE' AND LOWER(r.RoleName)=LOWER(?)";try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,id);p.setString(2,role);try(ResultSet r=p.executeQuery()){return r.next()&&r.getInt(1)>0;}}catch(SQLException e){return false;}}
 public List<CustomerOption> customers(){List<CustomerOption> out=new ArrayList<>();try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement("SELECT CustomerID,CustomerName,Phone FROM CUSTOMERS WHERE Status='ACTIVE' ORDER BY CustomerName");ResultSet r=p.executeQuery()){while(r.next()){CustomerOption x=new CustomerOption();x.setCustomerId(r.getInt(1));x.setCustomerName(r.getString(2));x.setPhone(r.getString(3));out.add(x);}}catch(SQLException e){LOG.log(Level.SEVERE,"customers",e);}return out;}
 public int create(int user,int customer,List<ExportRequestItem> items,String note){try(Connection c=DBContext.getConnection()){c.setAutoCommit(false);int id;try(PreparedStatement p=c.prepareStatement("INSERT INTO EXPORT_REQUESTS(CustomerID,CreatedBy,Status,CancelReason) OUTPUT INSERTED.ExportRequestID VALUES(?,?,'PENDING',?)")){p.setInt(1,customer);p.setInt(2,user);p.setString(3,note);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("request id");id=r.getInt(1);}}try(PreparedStatement p=c.prepareStatement("INSERT INTO EXPORT_REQUEST_DETAILS(ExportRequestID,ProductID,Quantity) VALUES(?,?,?)")){for(ExportRequestItem i:items){p.setInt(1,id);p.setInt(2,i.getProductId());p.setInt(3,i.getQuantity());p.addBatch();}p.executeBatch();}c.commit();return id;}catch(SQLException e){LOG.log(Level.WARNING,"create export request",e);return -1;}}
 public List<ExportRequest> salesRequests(int user){return requestList(" AND r.CreatedBy=?",user,"ALL");}
 public List<ExportRequest> managerRequests(String status){return requestList("",0,status);}
 public List<ExportRequest> assignedRequests(int user){return requestList(" AND r.AssignedTo=? AND r.Status='APPROVED' AND NOT EXISTS (SELECT 1 FROM EXPORT_RECEIPTS er WHERE er.ExportRequestID=r.ExportRequestID AND er.Status='PENDING_MANAGER')",user,"ALL");}
 private List<ExportRequest> requestList(String extra,int user,String status){List<ExportRequest> out=new ArrayList<>();String q="SELECT r.*,c.CustomerName,u.FullName CreatedByName,w.FullName AssignedName FROM EXPORT_REQUESTS r JOIN CUSTOMERS c ON c.CustomerID=r.CustomerID JOIN USERS u ON u.UserID=r.CreatedBy LEFT JOIN USERS w ON w.UserID=r.AssignedTo WHERE (?='ALL' OR r.Status=?)"+extra+" ORDER BY CASE WHEN r.Status='PENDING' THEN 0 WHEN r.Status='APPROVED' THEN 1 ELSE 2 END,r.RequestDate DESC";try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,status);p.setString(2,status);if(user>0)p.setInt(3,user);try(ResultSet r=p.executeQuery()){while(r.next())out.add(mapRequest(r));}for(ExportRequest r:out)r.setItems(requestItems(c,r.getRequestId()));}catch(SQLException e){LOG.log(Level.SEVERE,"request list",e);}return out;}
 public ExportRequest findRequest(int id){String q="SELECT r.*,c.CustomerName,u.FullName CreatedByName,w.FullName AssignedName FROM EXPORT_REQUESTS r JOIN CUSTOMERS c ON c.CustomerID=r.CustomerID JOIN USERS u ON u.UserID=r.CreatedBy LEFT JOIN USERS w ON w.UserID=r.AssignedTo WHERE r.ExportRequestID=?";try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,id);try(ResultSet r=p.executeQuery()){if(r.next()){ExportRequest x=mapRequest(r);x.setItems(requestItems(c,id));return x;}}}catch(SQLException e){LOG.log(Level.SEVERE,"request",e);}return null;}
 public boolean decideRequest(int id,int manager,int staff,boolean approve,String reason){try(Connection c=DBContext.getConnection()){c.setAutoCommit(false);int state;try(PreparedStatement p=c.prepareStatement("SELECT Status FROM EXPORT_REQUESTS WITH(UPDLOCK,HOLDLOCK) WHERE ExportRequestID=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){if(!r.next()||!"PENDING".equals(r.getString(1)))return rollback(c);}}
   try(PreparedStatement p=c.prepareStatement("SELECT ProductID,Quantity FROM EXPORT_REQUEST_DETAILS WHERE ExportRequestID=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){boolean any=false;while(r.next()){any=true;if(approve){try(PreparedStatement a=c.prepareStatement("SELECT COUNT(*) FROM INVENTORY WITH(UPDLOCK,HOLDLOCK) WHERE ProductID=? AND Status='IN_STOCK'")){a.setInt(1,r.getInt(1));try(ResultSet ar=a.executeQuery()){if(!ar.next()||ar.getInt(1)<r.getInt(2))return rollback(c);}}}}if(!any)return rollback(c);}}
   String q=approve?"UPDATE EXPORT_REQUESTS SET Status='APPROVED',AssignedTo=?,ApprovedBy=?,ApprovedDate=GETDATE(),CancelReason=NULL WHERE ExportRequestID=? AND Status='PENDING'":"UPDATE EXPORT_REQUESTS SET Status='REJECTED',ApprovedBy=?,ApprovedDate=GETDATE(),CancelReason=? WHERE ExportRequestID=? AND Status='PENDING'";try(PreparedStatement p=c.prepareStatement(q)){if(approve){p.setInt(1,staff);p.setInt(2,manager);p.setInt(3,id);}else{p.setInt(1,manager);p.setString(2,reason);p.setInt(3,id);}if(p.executeUpdate()!=1)return rollback(c);}c.commit();return true;
  }catch(SQLException e){LOG.log(Level.WARNING,"decide export request",e);return false;}}
 public List<InventoryOption> availableInventory(int requestId,int staff){List<InventoryOption> out=new ArrayList<>();String q="SELECT i.InventoryID,i.ProductID,p.ProductCode,p.ProductName,i.SerialNumber,i.Location FROM INVENTORY i JOIN PRODUCTS p ON p.ProductID=i.ProductID JOIN EXPORT_REQUEST_DETAILS d ON d.ProductID=i.ProductID AND d.ExportRequestID=? JOIN EXPORT_REQUESTS r ON r.ExportRequestID=d.ExportRequestID WHERE r.AssignedTo=? AND r.Status='APPROVED' AND i.Status='IN_STOCK' ORDER BY p.ProductCode,i.Location,i.SerialNumber";try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,requestId);p.setInt(2,staff);try(ResultSet r=p.executeQuery()){while(r.next()){InventoryOption x=new InventoryOption();x.setInventoryId(r.getInt(1));x.setProductId(r.getInt(2));x.setProductCode(r.getString(3));x.setProductName(r.getString(4));x.setSerialNumber(r.getString(5));x.setLocation(r.getString(6));out.add(x);}}}catch(SQLException e){LOG.log(Level.SEVERE,"available serials",e);}return out;}
 public int createReceipt(int id,int staff,String[] serials,String note){try(Connection c=DBContext.getConnection()){c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement("SELECT Status FROM EXPORT_REQUESTS WITH(UPDLOCK,HOLDLOCK) WHERE ExportRequestID=? AND AssignedTo=?")){p.setInt(1,id);p.setInt(2,staff);try(ResultSet r=p.executeQuery()){if(!r.next()||!"APPROVED".equals(r.getString(1)))return rollbackInt(c);}}
   Map<Integer,Integer> expected=new HashMap<>(),actual=new HashMap<>();try(PreparedStatement p=c.prepareStatement("SELECT ProductID,Quantity FROM EXPORT_REQUEST_DETAILS WHERE ExportRequestID=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){while(r.next())expected.put(r.getInt(1),r.getInt(2));}}if(serials==null||serials.length==0)return rollbackInt(c);Set<String> unique=new HashSet<>();List<ExportReceiptItem> selected=new ArrayList<>();for(String serial:serials){if(serial==null||serial.isBlank()||!unique.add(serial.trim().toUpperCase()))return rollbackInt(c);try(PreparedStatement p=c.prepareStatement("SELECT i.InventoryID,i.ProductID,p.ProductCode,p.ProductName,i.SerialNumber,i.Location, i.Status FROM INVENTORY i WITH(UPDLOCK,HOLDLOCK) JOIN PRODUCTS p ON p.ProductID=i.ProductID WHERE i.SerialNumber=?")){p.setString(1,serial.trim());try(ResultSet r=p.executeQuery()){if(!r.next()||!"IN_STOCK".equals(r.getString("Status"))||!expected.containsKey(r.getInt("ProductID")))return rollbackInt(c);ExportReceiptItem x=new ExportReceiptItem();x.setInventoryId(r.getInt("InventoryID"));x.setProductId(r.getInt("ProductID"));x.setProductCode(r.getString("ProductCode"));x.setProductName(r.getString("ProductName"));x.setSerialNumber(r.getString("SerialNumber"));x.setLocation(r.getString("Location"));selected.add(x);actual.merge(x.getProductId(),1,Integer::sum);}}}if(!expected.equals(actual))return rollbackInt(c);
   try(PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM EXPORT_RECEIPTS WITH(UPDLOCK,HOLDLOCK) WHERE ExportRequestID=? AND Status='PENDING_MANAGER'")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){if(r.next()&&r.getInt(1)>0)return rollbackInt(c);}}
   int receipt;try(PreparedStatement p=c.prepareStatement("INSERT INTO EXPORT_RECEIPTS(ExportRequestID,UserID,Status,Note) OUTPUT INSERTED.ExportReceiptID VALUES(?,?,'PENDING_MANAGER',?)")){p.setInt(1,id);p.setInt(2,staff);p.setString(3,note);try(ResultSet r=p.executeQuery()){if(!r.next())return rollbackInt(c);receipt=r.getInt(1);}}
   try(PreparedStatement detail=c.prepareStatement("INSERT INTO EXPORT_RECEIPT_DETAILS(ExportReceiptID,InventoryID,ProductID,SerialNumber) VALUES(?,?,?,?)");PreparedStatement reserve=c.prepareStatement("UPDATE INVENTORY SET Status='RESERVED',UpdatedAt=GETDATE() WHERE InventoryID=? AND Status='IN_STOCK'")){for(ExportReceiptItem x:selected){detail.setInt(1,receipt);detail.setInt(2,x.getInventoryId());detail.setInt(3,x.getProductId());detail.setString(4,x.getSerialNumber());detail.addBatch();reserve.setInt(1,x.getInventoryId());reserve.addBatch();}detail.executeBatch();int[] changed=reserve.executeBatch();for(int n:changed)if(n!=1&&n!=Statement.SUCCESS_NO_INFO)throw new SQLException("inventory item is no longer available");}c.commit();return receipt;
  }catch(SQLException e){LOG.log(Level.WARNING,"create export receipt",e);return -1;}}
 public List<ExportReceipt> receipts(String status){List<ExportReceipt> out=new ArrayList<>();String q="SELECT er.*,c.CustomerName,w.FullName WarehouseName,m.FullName ManagerName FROM EXPORT_RECEIPTS er JOIN EXPORT_REQUESTS r ON r.ExportRequestID=er.ExportRequestID JOIN CUSTOMERS c ON c.CustomerID=r.CustomerID JOIN USERS w ON w.UserID=er.UserID LEFT JOIN USERS m ON m.UserID=er.ApprovedBy WHERE (?='ALL' OR er.Status=?) ORDER BY CASE WHEN er.Status='PENDING_MANAGER' THEN 0 ELSE 1 END,er.ExportDate DESC";try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,status);p.setString(2,status);try(ResultSet r=p.executeQuery()){while(r.next()){ExportReceipt x=new ExportReceipt();x.setReceiptId(r.getInt("ExportReceiptID"));x.setRequestId(r.getInt("ExportRequestID"));x.setCustomerName(r.getString("CustomerName"));x.setWarehouseName(r.getString("WarehouseName"));x.setManagerName(r.getString("ManagerName"));x.setStatus(r.getString("Status"));x.setNote(r.getString("Note"));x.setCancelReason(r.getString("CancelReason"));x.setReceiptDate(r.getTimestamp("ExportDate"));x.setApprovedDate(r.getTimestamp("ApprovedDate"));out.add(x);}}for(ExportReceipt x:out)x.setItems(receiptItems(c,x.getReceiptId()));}catch(SQLException e){LOG.log(Level.SEVERE,"export receipts",e);}return out;}
 public List<ExportReceipt> receiptsByStaff(int staff){List<ExportReceipt> out=new ArrayList<>();String q="SELECT er.*,c.CustomerName,w.FullName WarehouseName,m.FullName ManagerName FROM EXPORT_RECEIPTS er JOIN EXPORT_REQUESTS r ON r.ExportRequestID=er.ExportRequestID JOIN CUSTOMERS c ON c.CustomerID=r.CustomerID JOIN USERS w ON w.UserID=er.UserID LEFT JOIN USERS m ON m.UserID=er.ApprovedBy WHERE er.UserID=? ORDER BY er.ExportDate DESC";try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,staff);try(ResultSet r=p.executeQuery()){while(r.next()){ExportReceipt x=new ExportReceipt();x.setReceiptId(r.getInt("ExportReceiptID"));x.setRequestId(r.getInt("ExportRequestID"));x.setCustomerName(r.getString("CustomerName"));x.setWarehouseName(r.getString("WarehouseName"));x.setManagerName(r.getString("ManagerName"));x.setStatus(r.getString("Status"));x.setNote(r.getString("Note"));x.setCancelReason(r.getString("CancelReason"));x.setReceiptDate(r.getTimestamp("ExportDate"));x.setApprovedDate(r.getTimestamp("ApprovedDate"));out.add(x);}}for(ExportReceipt x:out)x.setItems(receiptItems(c,x.getReceiptId()));}catch(SQLException e){LOG.log(Level.SEVERE,"staff receipts",e);}return out;}
 public boolean decideReceipt(int id,int manager,boolean approve,String reason){try(Connection c=DBContext.getConnection()){c.setAutoCommit(false);List<Integer> inventory=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT d.InventoryID FROM EXPORT_RECEIPT_DETAILS d WITH(UPDLOCK) JOIN EXPORT_RECEIPTS er WITH(UPDLOCK) ON er.ExportReceiptID=d.ExportReceiptID WHERE er.ExportReceiptID=? AND er.Status='PENDING_MANAGER'")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){while(r.next())inventory.add(r.getInt(1));}}if(inventory.isEmpty())return rollback(c);String invStatus=approve?"EXPORTED":"IN_STOCK";try(PreparedStatement p=c.prepareStatement("UPDATE INVENTORY SET Status=?,UpdatedAt=GETDATE() WHERE InventoryID=? AND Status='RESERVED'")){for(int v:inventory){p.setString(1,invStatus);p.setInt(2,v);if(p.executeUpdate()!=1)return rollback(c);}}
   try(PreparedStatement p=c.prepareStatement("UPDATE EXPORT_RECEIPTS SET Status=?,ApprovedBy=?,ApprovedDate=GETDATE(),CancelReason=? WHERE ExportReceiptID=? AND Status='PENDING_MANAGER'")){p.setString(1,approve?"COMPLETED":"REJECTED");p.setInt(2,manager);p.setString(3,approve?null:reason);p.setInt(4,id);if(p.executeUpdate()!=1)return rollback(c);}
   if(approve){try(PreparedStatement p=c.prepareStatement("UPDATE EXPORT_REQUESTS SET Status='COMPLETED' WHERE ExportRequestID=(SELECT ExportRequestID FROM EXPORT_RECEIPTS WHERE ExportReceiptID=?) AND Status='APPROVED'")){p.setInt(1,id);if(p.executeUpdate()!=1)return rollback(c);}}c.commit();return true;
  }catch(SQLException e){LOG.log(Level.WARNING,"decide export receipt",e);return false;}}
 private List<ExportRequestItem> requestItems(Connection c,int id)throws SQLException{List<ExportRequestItem> out=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT d.ProductID,d.Quantity,p.ProductCode,p.ProductName,(SELECT COUNT(*) FROM INVENTORY i WHERE i.ProductID=d.ProductID AND i.Status='IN_STOCK') AvailableQuantity FROM EXPORT_REQUEST_DETAILS d JOIN PRODUCTS p ON p.ProductID=d.ProductID WHERE d.ExportRequestID=? ORDER BY d.ExportRequestDetailID")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){while(r.next()){ExportRequestItem x=new ExportRequestItem();x.setProductId(r.getInt(1));x.setQuantity(r.getInt(2));x.setProductCode(r.getString(3));x.setProductName(r.getString(4));x.setAvailableQuantity(r.getInt(5));out.add(x);}}}return out;}
 private List<ExportReceiptItem> receiptItems(Connection c,int id)throws SQLException{List<ExportReceiptItem> out=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT d.InventoryID,d.ProductID,d.SerialNumber,i.Location,p.ProductCode,p.ProductName FROM EXPORT_RECEIPT_DETAILS d JOIN INVENTORY i ON i.InventoryID=d.InventoryID JOIN PRODUCTS p ON p.ProductID=d.ProductID WHERE d.ExportReceiptID=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){while(r.next()){ExportReceiptItem x=new ExportReceiptItem();x.setInventoryId(r.getInt(1));x.setProductId(r.getInt(2));x.setSerialNumber(r.getString(3));x.setLocation(r.getString(4));x.setProductCode(r.getString(5));x.setProductName(r.getString(6));out.add(x);}}}return out;}
 private ExportRequest mapRequest(ResultSet r)throws SQLException{ExportRequest x=new ExportRequest();x.setRequestId(r.getInt("ExportRequestID"));x.setCustomerId(r.getInt("CustomerID"));x.setAssignedTo(r.getInt("AssignedTo"));x.setCustomerName(r.getString("CustomerName"));x.setCreatedByName(r.getString("CreatedByName"));x.setAssignedName(r.getString("AssignedName"));x.setStatus(r.getString("Status"));x.setCancelReason(r.getString("CancelReason"));x.setRequestDate(r.getTimestamp("RequestDate"));x.setApprovedDate(r.getTimestamp("ApprovedDate"));return x;}
 private boolean rollback(Connection c){try{c.rollback();}catch(SQLException ignored){}return false;}private int rollbackInt(Connection c){rollback(c);return -1;}
}
